from collections import defaultdict,deque
def comps_of(di,bg):
    H,W=len(di),len(di[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for y in range(H):
        for x in range(W):
            if di[y][x]!=bg and not seen[y][x]:
                c=(di[y][x],); q=deque([(y,x)]); seen[y][x]=True; cc=set()
                while q:
                    cy,cx=q.popleft(); cc.add((cy,cx))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and di[ny][nx]==di[cy][cx] and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(cc)
    return out
def normc(cc):
    ys=[y for y,x in cc]; xs=[x for y,x in cc]
    return frozenset((y-min(ys),x-min(xs)) for y,x in cc)
def mindist(a,b):
    return min(abs(y1-y2)+abs(x1-x2) for y1,x1 in a for y2,x2 in b)
