    fam=[kk for kk,vv in fams.items() if len(vv)>=2]
    # duplicate families with exactly 2 members
    fam=[kk for kk in fam if len(fams[kk])==2]
    kk,fv=max(fam,key=lambda t:len(t[0]))
    uniqs=[p for p in cl if len([q for q in cl if q[0]==p[0]])==1]
