    inter=[u for u in fv if not any(y==0 or y==len(di_)-1 or x==0 or x==len(di_[0])-1 for y,x in u)]
    far=max(inter,key=d) if inter else max(fv,key=d)
    out=[r[:] for r in di_]
    for y,x in far: out[y][x]=mk[0]
