    ccols=Counter([di_[min(cl[ci])[0]][min(cl[ci])[1]] for ci in range(len(cl))])
    cand=[]
    for ci in range(len(cl)):
        if ccols[di_[min(cl[ci])[0]][min(cl[ci])[1]]]==1 and len(cl[ci])>1:
            cand.append(cl[ci])
    mk=max(cand,key=len)
    out=[r[:] for r in di_]
    for k,cs in [(k,v) for k,v in fam.items() if len(v)==2]:
        c1,c2=cl[cs[0]],cl[cs[1]]
        d1,d2=mind(c1,mk),mind(c2,mk)
        tgt=c1 if d1>d2 else c2
        mc=di_[min(mk)[0]][min(mk)[1]]
        for y,x in tgt: out[y][x]=mc
    return out
